package fraymus.workspace;

import org.json.*;
import org.junit.*;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;

/** Real native execution with explicitly labelled software host observations; actual Chromium tests are separate. */
public class SkillGraph046Test {
    static Path seed;static JSONObject skill,c;
    static class F implements AutoCloseable {
        final Path root;final WorkspaceStore artifacts;final SceneStore scenes;final BrainService brain;final GoalRunner goals;final WorkflowRunner workflows;
        F(Path root)throws Exception{this.root=root;artifacts=new WorkspaceStore(root);scenes=new SceneStore(root);brain=new BrainService(root);var data=new MeasurementStore(root);goals=new GoalRunner(root,scenes,brain,artifacts,data);workflows=new WorkflowRunner(root,goals,data,scenes,artifacts);}
        public void close()throws Exception{workflows.close();goals.close();brain.close();scenes.close();artifacts.close();}
        JSONObject world()throws Exception{var w=goals.worlds().create(WorldLedgerTest.source(c),"LABELLED046 Java test world");return goals.worlds().observe(w.getString("id"));}
        JSONObject input(JSONObject w){return new JSONObject().put("graph",graph()).put("worldBinding",SkillGraph046.typed(SkillGraph046Test.binding(w))).put("request","Run two exact retained procedures and compare their original native outcomes").put("title","LABELLED046 Java graph").put("modelName","software-host-fixture").put("saveSkillName","connected-world-046");}
    }
    static JSONObject binding(JSONObject observed){var b=new JSONObject();for(String k:List.of("worldId","expectedRevision","expectedHash"))b.put(k,observed.get(k));return b;}
    static JSONObject graph(){var nodes=new JSONArray();for(int i=0;i<2;i++){var step=c.getJSONArray("steps").getJSONObject(i);nodes.put(new JSONObject().put("id",i==0?"first":"second").put("kind","procedure").put("skill",SkillGraph046.ref(skill)).put("source",i==0?"world":"first").put("unit","m").put("frame","native3d").put("targets",step.getJSONArray("targets")).put("forceLimitN",step.getDouble("forceLimitN")).put("torqueLimitNm",step.getDouble("torqueLimitNm")));}return new JSONObject().put("schema",SkillGraph046.SCHEMA).put("nodes",nodes.put(new JSONObject().put("id","compare").put("kind","compare").put("sources",new JSONArray(List.of("first","second")))));}
    static void host(F f)throws Exception{
        var e=f.goals.claim();if(!e.has("id"))return;hostEffect(f,e);
    }
    static void hostEffect(F f,JSONObject e)throws Exception{assertEquals("canvas.verify-report",e.getString("kind"));var ref=e.getJSONObject("report");var checks=new JSONArray();int i=0;for(Object raw:e.getJSONArray("steps")){var s=(JSONObject)raw;checks.put(new JSONObject().put("index",i++).put("selector",s.getString("selector")).put("passed",true).put("actual",new JSONObject().put("text",s.optString("expectText")).put("count",s.optInt("expectCount",1))));}
        var tested=f.artifacts.recordTest(new JSONObject().put("id",ref.getString("id")).put("version",ref.getInt("version")).put("steps",e.getJSONArray("steps")).put("checks",checks));var g=f.goals.read(e.getString("goalId"));var run=f.goals.worldNative().run(g.getString("runId"));var frames=new JSONArray();for(Object raw:WorldReport.charts(run)){var ch=(JSONObject)raw;frames.put(new JSONObject().put("mode",ch.getString("mode")).put("points",ch.getJSONArray("points")));}
        tested.put("poseView",new JSONObject().put("visible",true).put("rows",WorldReport.table(run)).put("data",WorldReport.data(run)).put("frames",frames));f.goals.acknowledge(new JSONObject().put("goalId",e.getString("goalId")).put("id",e.getString("id")).put("nonce",e.getString("nonce")).put("result",tested));
    }
    interface Check {JSONObject read() throws Exception;}
    static JSONObject waitFor(F f,Check check)throws Exception{long end=System.nanoTime()+240_000_000_000L;while(System.nanoTime()<end){host(f);var result=check.read();if(result!=null)return result;Thread.sleep(10);}throw new AssertionError("Actual native graph deadline exceeded");}
    static JSONObject auditFixture(F f,JSONObject w)throws Exception{var a=f.artifacts.read(w.getJSONObject("report").getString("id"));var data=GraphReport046.data(w);var rows=new JSONArray();for(Object raw:data.getJSONArray("rows")){var row=new JSONArray();for(Object cell:(JSONArray)raw)row.put(String.valueOf(cell));rows.put(row);}return new JSONObject().put("id",a.getString("id")).put("version",a.getInt("version")).put("data",data).put("rows",rows).put("points",data.getJSONArray("points")).put("visible",true).put("viewBox",new JSONArray(List.of(0,0,800,300)));}
    static JSONObject finish(F f,String id)throws Exception{var e=waitFor(f,()->{var w=f.workflows.read(id);if(w.getString("status").equals("interrupted"))throw new AssertionError(w.toString());var claim=f.workflows.claim();return claim.has("id")?claim:null;});var w=f.workflows.read(id);f.workflows.acknowledge(new JSONObject().put("workflowId",id).put("id",e.getString("id")).put("nonce",e.getString("nonce")).put("result",auditFixture(f,w)));return waitFor(f,()->{var x=f.workflows.read(id);return x.getString("status").equals("running")?null:x;});}
    @BeforeClass public static void originalVerifiedSkill()throws Exception{
        c=WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0);seed=Files.createTempDirectory("graph046-seed-");
        try(var f=new F(seed)){var w=f.world();var args=WorldLedgerTest.args(w,c.getJSONArray("steps").getJSONObject(0)).put("saveSkillName","original-world-route");String id=f.goals.startWorld(args).getString("id");waitFor(f,()->{var g=f.goals.read(id);if(g.getString("status").equals("interrupted"))throw new AssertionError(g.toString());return g.getString("status").equals("completed")?g:null;});skill=f.goals.procedures().getJSONObject(0);}
    }
    static F fresh()throws Exception{Path root=Files.createTempDirectory("graph046-test-");try(var paths=Files.walk(seed)){for(Path p:paths.toList()){var q=root.resolve(seed.relativize(p));if(Files.isDirectory(p))Files.createDirectories(q);else Files.copy(p,q);}}return new F(root);}
    @Test public void actualTwoNodeChainChecksOriginalReportsAndRetainsExactGraphAfterRestart()throws Exception{
        Path root;String id,world;JSONObject result;
        try(var f=fresh()){root=f.root;var w=f.world();world=w.getString("worldId");id=f.workflows.start(f.input(w)).getString("id");result=finish(f,id);assertEquals("completed",result.getString("status"));assertEquals(2,result.getJSONObject("metrics").getInt("worldCommits"));assertEquals(0,result.getJSONObject("metrics").getInt("modelCalls"));assertEquals(2,f.goals.worlds().observe(world).getInt("expectedRevision"));var first=result.getJSONArray("stages").getJSONObject(0).getJSONObject("output");var second=result.getJSONArray("stages").getJSONObject(1).getJSONObject("output");assertTrue(first.getJSONObject("world").similar(second.getJSONObject("input")));assertEquals(first.getString("sha256"),second.getString("previousSha256"));assertNotEquals(first.getString("goalId"),second.getString("goalId"));assertTrue(result.getJSONObject("audit").getBoolean("passed"));Files.writeString(root.resolve("graph046-proof.json"),result.toString(2));}
        try(var f=new F(root)){var fresh=f.world();var reused=f.workflows.reuse(new JSONObject().put("name","connected-world-046").put("version",1).put("worldBinding",SkillGraph046.typed(binding(fresh))));assertNotEquals(id,reused.getString("id"));assertEquals(SkillGraph046.KIND,reused.getString("procedure"));assertEquals(fresh.getString("worldId"),reused.getJSONObject("worldBinding").getString("worldId"));f.workflows.cancel(reused.getString("id"));}System.out.println("GRAPH046_NATIVE_PROOF "+root);
    }
    @Test public void commitBeforeParentCheckpointReconcilesSameChildWithoutReplayingMovement()throws Exception{
        Path root;String id,goal,run,world;
        try(var f=fresh()){root=f.root;var w=f.world();world=w.getString("worldId");id=f.workflows.start(f.input(w)).getString("id");JSONObject claimed=null;long until=System.nanoTime()+120_000_000_000L;while(System.nanoTime()<until){var e=f.goals.claim();if(e.has("id")){claimed=e;break;}Thread.sleep(10);}assertNotNull(claimed);
            synchronized(f.workflows){goal=claimed.getString("goalId");run=f.goals.read(goal).getString("runId");hostEffect(f,claimed);while(!f.goals.read(goal).getString("status").equals("completed")&&System.nanoTime()<until)Thread.sleep(10);assertEquals("completed",f.goals.read(goal).getString("status"));assertEquals(1,f.goals.worlds().observe(world).getInt("expectedRevision"));assertFalse(f.workflows.read(id).getJSONArray("stages").getJSONObject(0).has("output"));f.workflows.close();}
        }
        try(var f=new F(root)){assertEquals("interrupted",f.workflows.read(id).getString("status"));f.workflows.resume(id);var result=finish(f,id);assertEquals("completed",result.getString("status"));assertEquals(goal,result.getJSONArray("stages").getJSONObject(0).getString("goalId"));assertEquals(run,result.getJSONArray("stages").getJSONObject(0).getString("runId"));assertEquals(2,f.goals.worlds().observe(world).getInt("expectedRevision"));}
    }
    @Test public void typeCyclesSkillChangesAndAuthorityAreRefusedBeforeAnyNewEffect()throws Exception{
        try(var f=fresh()){var w=f.world();int count=f.goals.list().length();var base=f.input(w);
            var bad=WorldFrames.copy(base);bad.getJSONObject("worldBinding").put("unit","pixels");assertThrows(Exception.class,()->f.workflows.start(bad));
            var cycle=WorldFrames.copy(base);cycle.getJSONObject("graph").getJSONArray("nodes").getJSONObject(0).put("source","second");assertThrows(Exception.class,()->f.workflows.start(cycle));
            var foreign=WorldFrames.copy(base);foreign.getJSONObject("graph").getJSONArray("nodes").getJSONObject(1).getJSONObject("skill").put("sha256","a".repeat(64));assertThrows(Exception.class,()->f.workflows.start(foreign));
            var authority=WorldFrames.copy(base);authority.getJSONObject("graph").getJSONArray("nodes").getJSONObject(1).put("forceLimitN",61);assertThrows(Exception.class,()->f.workflows.start(authority));
            var handler=WorldFrames.copy(base);handler.getJSONObject("graph").getJSONArray("nodes").getJSONObject(1).put("handler","shell");assertThrows(Exception.class,()->f.workflows.start(handler));
            var stale=WorldFrames.copy(base);stale.getJSONObject("worldBinding").put("expectedHash","a".repeat(64));assertThrows(Exception.class,()->f.workflows.start(stale));assertEquals(count,f.goals.list().length());assertFalse(f.goals.workflowReserved());assertEquals(0,f.goals.worlds().observe(w.getString("worldId")).getInt("expectedRevision"));
        }
    }
    @Test public void losslessDiagnosticOriginsAndTamperedWitnessNeverBecomeSuccess(){var w=new JSONObject().put("diagnostics",new JSONArray()).put("resumes",0);SkillGraph046.diagnostic(w,"first","A  mismatch");SkillGraph046.diagnostic(w,"second","a mismatch");assertEquals(1,w.getJSONArray("diagnostics").length());assertEquals(2,w.getJSONArray("diagnostics").getJSONObject(0).getJSONArray("occurrences").length());var out=SkillGraph046.seal(new JSONObject().put("result","original"),"a".repeat(64));SkillGraph046.verifySeal(out,"a".repeat(64));out.put("result","edited");assertThrows(Exception.class,()->SkillGraph046.verifySeal(out,"a".repeat(64)));}
    @Test public void stopDuringActualMotionNeverStartsDependantsOrRetainsGraph()throws Exception{
        try(var f=fresh()){var observed=f.world();String id=f.workflows.start(f.input(observed)).getString("id");var first=waitFor(f,()->{var w=f.workflows.read(id);var child=w.optJSONObject("currentChild");return child!=null&&child.optString("step").equals("world-wait")?child:null;});f.workflows.cancel(id);var stopped=f.workflows.read(id);assertEquals("cancelled",stopped.getString("status"));assertEquals("cancelled",f.goals.read(first.getString("id")).getString("status"));assertEquals("cancelled",f.goals.worldNative().run(first.getString("runId")).getString("status"));assertFalse(stopped.getJSONArray("stages").getJSONObject(1).has("goalId"));assertFalse(stopped.has("savedSkill"));assertEquals(0,f.goals.worlds().observe(observed.getString("worldId")).getInt("expectedRevision"));assertFalse(f.goals.workflowReserved());}
    }
    @Test public void nativeInFlightRecoveryRetainsSameRunAndEveryCommittedPrefixSample()throws Exception{
        Path root;String id,goal,run;JSONObject prefix;
        try(var f=fresh()){root=f.root;id=f.workflows.start(f.input(f.world())).getString("id");var first=waitFor(f,()->{var w=f.workflows.read(id);var g=w.optJSONObject("currentChild");if(g==null||!g.has("runId")||!g.optString("step").equals("world-wait"))return null;return f.goals.worldNative().snapshot().optJSONObject("sample",new JSONObject()).optInt("tick")>80?g:null;});goal=first.getString("id");run=first.getString("runId");f.workflows.close();f.goals.close();var volatileTail=f.goals.worldNative().run(run);assertTrue(Set.of("paused","interrupted").contains(volatileTail.getString("status")));prefix=WorldNativeCheckpoint.read(root.resolve("world-native/checkpoints/"+run+".json"),run,volatileTail.getJSONObject("definition")).getJSONObject("payload").getJSONObject("run");Files.writeString(root.resolve("graph046-durable-prefix.json"),prefix.toString());}
        try(var f=new F(root)){f.workflows.resume(id);var done=finish(f,id);assertEquals("completed",done.getString("status"));var first=done.getJSONArray("stages").getJSONObject(0);assertEquals(goal,first.getString("goalId"));assertEquals(run,first.getString("runId"));var after=f.goals.worldNative().run(run);for(int i=0;i<prefix.getJSONArray("samples").length();i++)assertTrue("Committed native prefix sample changed at "+i,prefix.getJSONArray("samples").getJSONObject(i).similar(after.getJSONArray("samples").getJSONObject(i)));assertTrue(WorldVerify.verify(after).getBoolean("passed"));}
    }
    @Test public void exactMemoAuditsCorruptionAndNeverHidesMissingOriginalEvidence()throws Exception{
        try(var f=fresh()){var memo=new SkillGraph046.ContractMemo();var def=graph();var first=memo.get(def,f.goals);first.put("schema","edited copy");assertEquals(SkillGraph046.SCHEMA,memo.get(def,f.goals).getString("schema"));memo.get(def,f.goals);memo.get(def,f.goals);memo.entries.values().iterator().next().put("schema","poisoned cache");assertThrows(IllegalStateException.class,()->memo.get(def,f.goals));assertEquals(1,memo.invalidations);assertEquals(0,memo.entries.size());assertEquals(SkillGraph046.SCHEMA,memo.get(def,f.goals).getString("schema"));var p=WorldFrames.copy(skill);p.getJSONObject("defaults").put("forceLimitN",59);assertThrows(IllegalStateException.class,()->f.goals.verifyProcedure046(p));}
    }
}
